            domestic_rate = value['number_value']
        elif value['header3'] == 'International' and value['header1'] == '2019':
            international_rate = value['number_value']
    difference = domestic_rate - international_rate
    scale = 'percent' if 'scale' in [v['scale'] for v in value_list] and value_list[0]['scale'] == 'percent' else ''
