def run(value_list):
    # Find the discount rates for 2018 and 2019
    discount_2018 = next((val['number_value'] for val in value_list if val['category'] == 'Discount rate' and val['header3'] == 'Domestic' and val['header1'] == '2018'), None)
    discount_2019 = next((val['number_value'] for val in value_list if val['category'] == 'Discount rate' and val['header3'] == 'Domestic' and val['header1'] == '2019'), None)

    if discount_2018 is None or discount_2019 is None:
        return (0.0, '')

    # Calculate percentage change
    change = ((discount_2019 - discount_2018) / discount_2018) * 100
    return (round(change, 2), 'percent')

def run(value_list):
