    out_31_march_2019 = next((val['number_value'] for val in value_list if val['header1'] == 'Number' and val['header2'] == '2019' and val['category'] == 'Outstanding at 31 March'), 0.0)
    out_31_march_2018 = next((val['number_value'] for val in value_list if val['header1'] == 'Number' and val['header2'] == '2018' and val['category'] == 'Outstanding at 31 March'), 0.0)

    # Calculate the change
    change = out_31_march_2019 - out_31_march_2018

    # Determine the scale
    if abs(change) >= 1_000_000:
        scale = 'million'
    elif abs(change) >= 1_000:
        scale = 'thousand'
    else:
        scale = ''

    # Ensure the result is a float with two decimal places
    return (round(change, 2), scale)

def run(value_list):
    # Extract the values for Outstanding at 31 March for 2019 and 2018
    out_at_31_march_2019 = next(val for val in value_list if val['category'] == 'Outstanding at 31 March' and val['header2'] == '2019')['number_value']
    out_at_31_march_2018 = next(val for val in value_list if val['category'] == 'Outstanding at 31 March' and val['header2'] == '2018')['number_value']

    # Calculate the percentage change
    if out_at_31_march_2018 == 0:
        return (0.0, '')
    percentage_change = ((out_at_31_march_2019 - out_at_31_march_2018) / out_at_31_march_2018) * 100

    # Determine the scale
    if abs(percentage_change) < 1e-3:
        scale = ''
    elif abs(percentage_change) < 1e-2:
        scale = 'thousand'
    elif abs(percentage_change) < 1e-1:
        scale = 'million'
    elif abs(percentage_change) < 1e-0:
        scale = 'billion'
    else:
        scale = 'percent'

    return (round(percentage_change, 2), scale)

