def run(value_list):
    # Extract relevant values
    investment_income = []
    financing_costs = []

    for item in value_list:
        if item['category'] == 'Investment income':
            investment_income.append(item['number_value'])
        elif item['category'] == 'Financing costs':
            financing_costs.append(item['number_value'])

    # Calculate averages
    avg_investment = sum(investment_income) / len(investment_income) if investment_income else 0.0
    avg_financing = sum(financing_costs) / len(financing_costs) if financing_costs else 0.0

    # Determine scale
