    # Calculate the percentage
    percentage = (royalty_bearing_2019['number_value'] / total_revenue_2019['number_value']) * 100

    # Determine the scale
    if abs(percentage) >= 1_000_000_000:
        scale = 'billion'
    elif abs(percentage) >= 1_000_000:
        scale = 'million'
    elif abs(percentage) >= 1_000:
        scale = 'thousand'
    else:
        scale = ''

    # Return the result as a tuple (number, scale)
    return (percentage, scale)

def run(value_list):
    # Find 2019 closing balance of financial assets
    closing_2019_assets = next((val['number_value'] for val in value_list if val['header3'] == 'Financial assets' and val['header2'] == '2019' and val['category'] == 'Closing balance'), None)

    # Find 2018 closing balance of financial assets
    closing_2018_assets = next((val['number_value'] for val in value_list if val['header3'] == 'Financial assets' and val['header2'] == '2018' and val['category'] == 'Closing balance'), None)

    if closing_2019_assets is None or closing_2018_assets is None:
        return (0.0, '')

    percentage = (closing_2019_assets / closing_2018_assets) * 100
    return (percentage, 'percent')

def run(value_list):
