def run(value_list):
    # Extract the values for 2020 and 2021 operating leases
    operating_2020 = value_list[0]['number_value']
    operating_2021 = value_list[3]['number_value']

    # Calculate the percentage change
    change = (operating_2021 - operating_2020) / operating_2020 * 100

    # Determine the scale
    if operating_2020 == 0:
        scale = ''
    else:
        scale = 'million' if operating_2020 % 1000 == 0 else ''

    return (change, scale)

def run(value_list):
    # Find the entries related to carrying amount of interest rate swaps
    for entry in value_list:
        if entry['category'] == 'Carrying amount (non-current (liabilities)/assets' and entry['header3'] == '2019' and entry['header2'] == 'RMB’Million':
            carry_2019 = entry['number_value']
        if entry['category'] == 'Carrying amount (non-current (liabilities)/assets' and entry['header3'] == '2018' and entry['header2'] == 'RMB’Million':
            carry_2018 = entry['number_value']
    # Calculate the change
    change = carry_2019 - carry_2018
    # Determine scale
    if carry_2019 is not None and carry_2018 is not None:
        if 'million' in str(carry_2019):
            scale = 'million'
        elif 'million' in str(carry_2018):
            scale = 'million'
        else:
            scale = ''
    else:
        scale = ''
    return (change, scale)

def run(value_list):
    notional_2018 = None
    notional_2019 = None
    for item in value_list:
        if item['category'] == 'Notional amount':
            if item['header3'] == '2018':
                notional_2018 = item['number_value']
