def run(value_list):
    # Find the weighted average hedged rate for the year in 2019 and 2018
    rate_2019 = next((val['number_value'] for val in value_list if val['category'] == 'Weighted average hedged rate for the year' and val['header3'] == '2019'), None)
    rate_2018 = next((val['number_value'] for val in value_list if val['category'] == 'Weighted average hedged rate for the year' and val['header3'] == '2018'), None)

    if rate_2019 is None or rate_2018 is None:
        return (0.0, '')

    # Calculate percentage change
    change = (rate_2019 - rate_2018) / rate_2018
    return (round(change, 2), 'percent') if change != 0 else (0.0, '')

def run(value_list):
