def run(value_list):
    # Extract the GAAP-based Professional Service and Other Gross Margin % values
    gross_margin_percent_values = [val['number_value'] for val in value_list if val['category'] == 'GAAP-based Professional Service and Other Gross Margin %']

    # Check if there are any values to avoid division by zero
    if not gross_margin_percent_values:
        return (0.0, "")

    # Calculate the average
    average = sum(gross_margin_percent_values) / len(gross_margin_percent_values)

    # Format the result to two decimal places
    return (round(average, 2), "percent")

def run(value_list):
    # Find FCC licenses values for 2018 and 2019
    fcc_2018 = next((val['number_value'] for val in value_list if val['category'] == 'FCC licenses' and val['header1'] == '2018'), None)
    fcc_2019 = next((val['number_value'] for val in value_list if val['category'] == 'FCC licenses' and val['header1'] == '2019'), None)

    # Calculate the increase
    increase = fcc_2019 - fcc_2018

    # Determine scale
    if increase >= 1000000000:
        scale = 'billion'
    elif increase >= 1000000:
        scale = 'million'
    elif increase >= 1000:
        scale = 'thousand'
    else:
        scale = ''

    # Round to two decimal places
    number = round(increase, 2)

    return (number, scale)

def run(value_list):
    state_licenses = [item['number_value'] for item in value_list if item['category'] == 'State licenses']
    total_state = sum(state_licenses)
    count = len(state_licenses)
    average = total_state / count
    # Determine scale
    if average < 1000:
        scale = 'thousand'
    elif average < 1000000:
        scale = 'million'
    elif average < 1000000000:
        scale = 'billion'
    else:
        scale = ''
    return (average, scale)

def run(value_list):
    # Find the total values for 2018 and 2019
    total_2018 = value_list[1]['number_value']
    total_2019 = value_list[5]['number_value']

    # Calculate the percentage change
    percentage_change = ((total_2019 - total_2018) / total_2018) * 100 if total_2018 != 0 else 0

    # Determine the scale
    if abs(percentage_change) < 1:
        scale = 'percent'
    else:
        scale = ''

    return (percentage_change, scale)

def run(value_list):
    # Find vested value for 2019
    vested_value = None
    for entry in value_list:
        if entry['category'] == 'Vested' and entry['header2'] == 'Non-vested awards':
            vested_value = entry['number_value']

    # Find total non-vested shares at 2019
    total_non_vested = None
    for entry in value_list:
        if entry['category'] == 'Non-vested at December 31, 2019' and entry['header2'] == 'Non-vested awards':
            total_non_vested = entry['number_value']

    # Calculate percentage
    if vested_value is None or total_non_vested is None:
        return (0.0, '')
    percentage = (vested_value / total_non_vested) * 100

    # Round to two decimal places
    rounded_percentage = round(percentage, 2)

    # Determine scale
    if rounded_percentage == 0:
        scale = ''
    else:
        scale = 'percent'

    return (rounded_percentage, scale)

def run(value_list):
    # Find the total values for 2018 and 2019
    total_2018 = next(val['number_value'] for val in value_list if val['header1'] == '2018' and val['category'] == 'Total')
    total_2019 = next(val['number_value'] for val in value_list if val['header1'] == '2019' and val['category'] == 'Total')

    # Calculate percentage change
    if total_2018 == 0:
        return (0.0, 'percent')
    percentage_change = ((total_2019 - total_2018) / total_2018) * 100
    return (round(percentage_change, 2), 'percent')
